class Routes
  def initialize
    @lock = Thread::Mutex.new
    @snapshot = { routes: {}.freeze, version: 0 }.freeze
  end
  def lookup(key) = @snapshot[:routes][key]          # frozen snapshot: no lock
  def add(key, value)
    @lock.synchronize do                             # writers serialise
      routes = @snapshot[:routes].merge(key => value).freeze   # copy-on-write
      @snapshot = { routes: routes, version: @snapshot[:version] + 1 }.freeze
    end
  end
end
